#pragma once
#include <cstddef>
#include <cstdint>
#include <utility>

/// Data-dependency-width microbenchmark kernel (Test 1).
///
/// `dd::DdKernel<W>::run(extendedprice, discount)` produces W *distinct scalar*
/// int64 SSA locals that are each data-dependent on the per-tuple input columns
/// and all of which are reduced (summed) into a single returned int64. The W
/// locals are generated by recursive template / `if constexpr`-free integer
/// sequence unrolling -- no `std::array`, no runtime loop whose bound is W -- so
/// W is a *compile-time* constant and the machine code is straight-line
/// register-pressure.
namespace dd {

/// W-index-dependent distinct constant so neighbouring intermediate values can
/// neither be CSE'd together nor constant-folded away.
constexpr int64_t ddConstant(int k) {
   return 0x9E3779B97F4A7C15LL * (int64_t)(k + 1) +
          0x51ED270BLL * (int64_t)k + 0x2545F4914F6CDD1DLL;
}

template <int W>
struct DdKernel {
   /// Compile-time intermediate k (distinct scalar SSA local). Data-dependent
   /// on both columns: `ep * Ck + (ep ^ (disc + k))`.
   template <int k>
   static inline int64_t gen(int64_t extendedprice, int64_t discount) {
      return extendedprice * ddConstant(k) + (extendedprice ^ (discount + k));
   }

   template <int... ks>
   static inline int64_t sumAll(int64_t extendedprice, int64_t discount,
                                std::integer_sequence<int, ks...>) {
      // straight-line fold over all W locals: nothing can be dead-code
      // eliminated because every local feeds this reduction.
      return (gen<ks>(extendedprice, discount) + ...);
   }

   static inline int64_t run(int64_t extendedprice, int64_t discount) {
      return sumAll(extendedprice, discount,
                    std::make_integer_sequence<int, W>{});
   }
};

// ---------------------------------------------------------------------------
// Test 1b -- the *independent* (wide) kernel.
//
// DdKernel above computes every intermediate from the columns but reduces it
// through a running sum, so each v_k is dead as soon as it is added: live
// ranges are short and the allocator never spills (Task 1 measured an
// instruction-count effect, not register pressure).
//
// DdKernelIndep is identical in per-intermediate arithmetic (`ep * Ck +
// (ep ^ (disc + k))`, ~4 scalar ops each -- exactly the same expression as
// DdKernel, so arith parity is structural). It differs ONLY in live-set width:
// each v_k is computed into its own named scalar and pinned to a register by a
// zero-instruction asm scheduling barrier before the single final reduction.
// The barrier prevents the compiler from folding each value into a running sum
// as it is produced, so all W values are simultaneously live from their
// definitions to the reduction -> a WIDE live set -> genuine register pressure
// -> W-scaling spills once W exceeds the available GP registers.
// ---------------------------------------------------------------------------
template <int W>
struct DdKernelIndep {
   template <int k>
   static inline int64_t gen(int64_t extendedprice, int64_t discount) {
      int64_t v = extendedprice * ddConstant(k) +
                  (extendedprice ^ (discount + k));
      // Zero-instruction scheduling barrier: forces v to be materialized and
      // kept live in a register, and (being volatile) prevents the reduction
      // from being interleaved with the computation, so all W values stay live
      // until the final sum. Emits no instruction, so arith count is unchanged.
      asm volatile("" : "+r"(v));
      return v;
   }

   template <int... ks>
   static inline int64_t reduce(int64_t extendedprice, int64_t discount,
                                std::integer_sequence<int, ks...>) {
      // Single final reduction over all W independently-live values.
      return (gen<ks>(extendedprice, discount) + ...);
   }

   static inline int64_t run(int64_t extendedprice, int64_t discount) {
      return reduce(extendedprice, discount,
                    std::make_integer_sequence<int, W>{});
   }
};

// Kernel shape selector: pick the kernel type at compile time from a Shape.
enum class Shape { Chained, Independent };

template <int W, Shape S>
struct Kernel;
template <int W>
struct Kernel<W, Shape::Chained> {
   using type = DdKernel<W>;
};
template <int W>
struct Kernel<W, Shape::Independent> {
   using type = DdKernelIndep<W>;
};

// ---------------------------------------------------------------------------
// Test 3 -- tiered-reload kernel.
//
// Identical per-intermediate arithmetic to DdKernelIndep (`ep * Ck +
// (ep ^ (disc + k))`, ~4 scalar ops per intermediate).  Each intermediate
// is written to and read back from a scratch buffer whose stride is chosen
// so the reload working set lands in a specific cache tier.
//
// The Tier template parameter selects the target: L1, L2, LLC, or DRAM.
// Instruction count is identical across tiers at each W -- only the
// address (and therefore the cache level servicing the reload) changes.
//
// Target machine: Xeon Gold 6238 (Cascade Lake-SP), 4S/22C/2T.
// Per-core: L1d 32 KB, L2 1 MB.  Per-socket LLC: 30.25 MB.
// Tier buffer sizes chosen so that `W_max * stride_bytes` lands in the
// target level with margin:
//   L1:   16 KB working set  (fits in 32 KB L1d)
//   L2:   256 KB working set (overflows L1, fits in 1 MB L2)
//   LLC:  8 MB working set   (overflows L2, fits in 30 MB LLC)
//   DRAM: 128 MB working set (overflows 30 MB LLC)
//
// Stride per tier = tierBytes / W, rounded down to an odd multiple of a
// cache line (64 bytes) to avoid 4 KB aliasing and set conflicts.  Both
// W and Tier are compile-time, so the stride is constexpr and the
// store/load offsets fold into the addressing mode (no extra instructions).
// ---------------------------------------------------------------------------

enum class Tier { L1, L2, LLC, DRAM };

namespace detail {

// Target working-set size (bytes) per tier.
constexpr size_t tierBytes(Tier t) {
   switch (t) {
      case Tier::L1:   return 16UL * 1024;        // 16 KB
      case Tier::L2:   return 256UL * 1024;        // 256 KB
      case Tier::LLC:  return 8UL * 1024 * 1024;   // 8 MB
      case Tier::DRAM: return 128UL * 1024 * 1024; // 128 MB
   }
   return 16UL * 1024;
}

// Compute stride in int64_t units (8 bytes each).
// stride_bytes = tierBytes / W, rounded down to an odd multiple of 64.
// Minimum stride is 64 bytes (one cache line = 8 int64s).
constexpr size_t tierStride(Tier t, int W) {
   size_t raw = tierBytes(t) / static_cast<size_t>(W);
   // Round down to multiple of 64 bytes
   size_t lines = raw / 64;
   if (lines < 1) lines = 1;
   // Make odd to avoid power-of-two stride aliasing
   if (lines > 1 && (lines & 1) == 0) lines -= 1;
   // Return in int64_t units (bytes / 8)
   return (lines * 64) / 8;
}

// Total scratch buffer size in int64_t units.
constexpr size_t tierBufSize(Tier t, int W) {
   return tierStride(t, W) * static_cast<size_t>(W);
}

} // namespace detail

template <int W, Tier T>
struct DdKernelTiered {
   static constexpr size_t STRIDE = detail::tierStride(T, W);
   static constexpr size_t BUF_SIZE = detail::tierBufSize(T, W);

   // Compute intermediate k, write to scratch, barrier, read back.
   // The write+read forces the value through the cache hierarchy at the
   // tier determined by the buffer's total footprint.
   template <int k>
   static inline int64_t gen(int64_t extendedprice, int64_t discount,
                             int64_t* __restrict__ scratch) {
      int64_t v = extendedprice * ddConstant(k) +
                  (extendedprice ^ (discount + k));
      // Store to tier-specific scratch slot
      scratch[k * STRIDE] = v;
      // Scheduling barrier: ensures the store is committed before the
      // reload, and prevents the compiler from eliminating the round-trip.
      asm volatile("" ::: "memory");
      // Reload from the same slot -- this is the measured access.
      int64_t r = scratch[k * STRIDE];
      // Pin the reloaded value so it cannot be optimized away.
      asm volatile("" : "+r"(r));
      return r;
   }

   template <int... ks>
   static inline int64_t reduce(int64_t extendedprice, int64_t discount,
                                int64_t* __restrict__ scratch,
                                std::integer_sequence<int, ks...>) {
      return (gen<ks>(extendedprice, discount, scratch) + ...);
   }

   static inline int64_t run(int64_t extendedprice, int64_t discount,
                             int64_t* __restrict__ scratch) {
      return reduce(extendedprice, discount, scratch,
                    std::make_integer_sequence<int, W>{});
   }
};

// Tiered kernel selector (parallel to Kernel<W,S>).
template <int W, Tier T>
struct KernelTiered {
   using type = DdKernelTiered<W, T>;
};

}  // namespace dd
